async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  try {
    const summaries = (await sessionStore?.listFor?.(session.userId, listOptions(message))) ?? [];
    sendJson(ws, {type: 'session_list', sessions: summaries.map(toSummaryFrame)});
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    log.error('ws', 'session list failed', {userId: session.userId, error: errorMessage});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list sessions');
  }
}

function listOptions(message: ListSessionsMessage) {
  return {
    ...(message.limit !== undefined ? {limit: message.limit} : {}),
    ...(message.before !== undefined ? {before: message.before} : {}),
  };
}

function toSummaryFrame(summary: SessionSummary) {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}

